def icon(name):return '<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+icons[name]+'</svg>'
translations={
'en':dict(prefix='',langname='English',other='Español',otherlink='es/',label='Independent community project',nav=['The story','The app','Get started'],navid=['story','app','start'],support='Support',title='Nike Adapt Auto Max: a second life | Open Adapt',description='An independent Android project for Nike Adapt Auto Max. Explore local control, battery percentages, lighting, motion effects and GitHub app updates. English and Spanish.',headline='Good shoes.<br>Another chapter.',intro='Your Adapt still have a story to tell. Open Adapt explores a way to bring their connected controls back to your hands.',download='Get the Android app',source='Explore the source',experimental='Experimental · Android 7.0+',art='Reference-inspired concept artwork. Shoe behavior requires physical testing.',spec=['AUTO MAX','LOCAL CONTROL','COMMUNITY BUILT'],scroll='Made to keep moving',storylabel='01 / THE REASON',storytitle='I have the shoes.<br>I wanted the app back.',quote='“I own a pair of Nike Adapt. Without the app, they became unusable for the connected features I bought them for. I started Open Adapt because I wanted to use my shoes again.”',storybody='This project began with that very personal frustration. The goal is to explore a second life for the Auto Max: local controls, a clearer interface and a community that can keep learning how they work.',storynote='A personal account from the project creator. Basic shoe buttons may still operate independently of the original app.',featurelabel='02 / THE CONTROLS',featuretitle='A little more life.<br>A lot more control.',features=[('battery','Know your charge.','Separate left and right battery percentages from authenticated shoe readings. Missing data stays missing—never a made-up number.'),('light','Choose your light.','Color selection, individual light tests and a continuous-light mode that renews the effect while connected.'),('motion','Move with it.','Phone-turn effects through a foreground service, including with the screen off. Foot-strike mode only reacts if the shoes already emit events.'),('link','Keep your pair.','Reuse locally stored pairing keys after a real first pairing. Updates replace the app without clearing its data.'),('download','Stay up to date.','Check public GitHub releases from the app, verify the download and confirm the update in Android.'),('shield','Understand your firmware.','Read versions, reported checksums and image states, then export a diagnostic. Full firmware backup and cloning are not implemented.')],applabel='03 / IN YOUR HANDS',apptitle='Familiar purpose.<br>A fresh perspective.',apptext='Four focused screens. Clear battery cards. Colors you can see before selecting. A stop button that stays within reach.',apptabs=['Home','Lights','Motion','System'],screenshot='Actual Android emulator screens. No shoes connected; battery percentages are intentionally absent.',apknote='The app interface is currently in Spanish. This website is available in English and Spanish.',startlabel='04 / GET MOVING',starttitle='A new start.<br>Keep your pair.',steps=[('Download','Get the experimental APK from the official project release. Review the installation guide before trying it with your shoes.'),('Pair once','Allow Bluetooth / Nearby Devices and complete real physical pairing. The app cannot import the original Nike app’s private keys.'),('Update in place','For later versions, use System → App updates. Android asks you to approve installation; keep Open Adapt installed to retain local data.')],guide='Installation guide (Spanish)',updates='How updates work',statuslabel='OPEN DEVELOPMENT',statustitle='Experimental. Open about it.',status='The native interface and update policy have local tests. Actual Bluetooth pairing, battery readings, LEDs and lace-motor behavior still need validation on physical Auto Max shoes. Emulator checks do not establish hardware compatibility.',motor='Optional lace movement is off by default and requires confirmation. Audible motor effects are unverified. Shoe foot-strike streaming cannot currently be activated by this build.',validation='Read the validation report',faqlabel='A FEW THINGS TO KNOW',faqtitle='Before your next step.',faqs=[('Is this an official Nike app?','No. Open Adapt is an independent community project, with no affiliation or endorsement from Nike. Nike trademarks belong to their respective owners.'),('Will updates keep my pairing?','An in-place update with the same package and signing key preserves the app’s local data. A real first pairing is still necessary. Reconnection with physical shoes across an update remains to be validated. Uninstalling or clearing storage removes local data.'),('Can it clone one shoe’s firmware to the other?','No. The project can read firmware diagnostics, but it does not extract or restore a complete firmware image. Matching version numbers alone do not establish that images are interchangeable.'),('Do the Swoosh and every movement really light up?','The glowing Swoosh in the project artwork is an artistic treatment. Actual lighting effects depend on compatible shoe hardware and firmware. Phone turns do not identify individual footsteps.')],donatelabel='KEEP THE PROJECT MOVING',donatetitle='Help write the<br>next chapter.',donatetext='If you share the idea of giving Adapt a second life, you can support the time spent on research, testing and documentation.',donate='Donate with PayPal',donatenote='Optional support through PayPal. Donations do not promise compatibility or future features.',footer='Independent from Nike. Made for a second life.',top='Back to top',skip='Skip to content',privacy='No analytics or tracking cookies are added by this site. GitHub hosts these pages; GitHub and PayPal links open their own services.'),
'es':dict(prefix='../',langname='Español',other='English',otherlink='../',label='Proyecto independiente de la comunidad',nav=['La historia','La app','Comenzar'],navid=['story','app','start'],support='Apoyar',title='Nike Adapt Auto Max: una segunda vida | Open Adapt',description='Proyecto Android independiente para Nike Adapt Auto Max. Control local, porcentaje de batería, luces, efectos de movimiento y actualizaciones desde GitHub. Español e inglés.',headline='Tu par.<br>Otra vida.',intro='Tus Adapt todavía tienen historia por recorrer. Open Adapt explora cómo devolver el control de sus funciones conectadas a tus manos.',download='Obtener la app Android',source='Explorar el código',experimental='Experimental · Android 7.0+',art='Ilustración conceptual inspirada en la referencia. Falta validar el comportamiento físico.',spec=['AUTO MAX','CONTROL LOCAL','HECHO EN COMUNIDAD'],scroll='Hechas para seguir',storylabel='01 / EL MOTIVO',storytitle='Tengo las zapatillas.<br>Quería recuperar la app.',quote='«Tengo unas Nike Adapt. Sin la app, quedaron inservibles para las funciones conectadas por las que las compré. Empecé Open Adapt porque quería volver a usar mis zapatillas».',storybody='Este proyecto nació de esa frustración personal. La idea es explorar una segunda vida para las Auto Max: controles locales, una interfaz más clara y una comunidad que siga aprendiendo cómo funcionan.',storynote='Experiencia personal del creador del proyecto. Los botones básicos del calzado pueden seguir funcionando sin la app original.',featurelabel='02 / LOS CONTROLES',featuretitle='Más vida.<br>Más control.',features=[('battery','Conoce tu carga.','Porcentajes separados para izquierda y derecha, obtenidos de lecturas autenticadas. Si no hay datos, no se inventa una cifra.'),('light','Elige tu luz.','Selección de color, pruebas de cada lado y un modo de luz continua que renueva el efecto mientras hay conexión.'),('motion','Sigue el movimiento.','Efectos por giros del teléfono mediante un servicio en primer plano, incluso con pantalla apagada. El modo de pisadas solo responde si el calzado ya emite eventos.'),('link','Conserva tu par.','Reutiliza las claves guardadas después de un primer emparejamiento real. Las actualizaciones reemplazan la app sin borrar sus datos.'),('download','Mantente al día.','Consulta las versiones públicas de GitHub desde la app, verifica la descarga y confirma la actualización en Android.'),('shield','Conoce tu firmware.','Consulta versiones, checksums informados y estados de imagen. Exporta el diagnóstico. El respaldo completo y la clonación no están implementados.')],applabel='03 / EN TUS MANOS',apptitle='La misma intención.<br>Una nueva mirada.',apptext='Cuatro pantallas enfocadas. Tarjetas de batería claras. Colores visibles antes de elegir. Un botón para detener que sigue al alcance.',apptabs=['Inicio','Luces','Movimiento','Sistema'],screenshot='Capturas reales de un emulador Android, sin zapatillas conectadas. No se muestran porcentajes inventados.',apknote='La interfaz de la app está actualmente en español. Esta web está disponible en español e inglés.',startlabel='04 / A CAMINAR',starttitle='Un nuevo comienzo.<br>Conserva tu par.',steps=[('Descarga','Obtén el APK experimental desde la publicación oficial del proyecto. Lee la guía de instalación antes de probarlo con tus zapatillas.'),('Empareja una vez','Autoriza Bluetooth / Dispositivos cercanos y completa el emparejamiento físico. La app no puede importar las claves privadas de la app de Nike.'),('Actualiza encima','En las siguientes versiones, usa Sistema → Actualizaciones de la app. Android pide confirmar la instalación; conserva Open Adapt instalado para mantener sus datos.')],guide='Guía de instalación',updates='Cómo funcionan las actualizaciones',statuslabel='DESARROLLO ABIERTO',statustitle='Experimental. Con claridad.',status='La interfaz nativa y las reglas de actualización tienen pruebas locales. El emparejamiento Bluetooth, las lecturas de batería, los LED y el motor todavía necesitan validación con Auto Max físicas. Las pruebas de emulador no demuestran compatibilidad con el calzado.',motor='El movimiento opcional de cordones está desactivado inicialmente y requiere confirmación. El sonido del motor no está verificado. Esta versión no puede activar el envío de eventos de pisadas.',validation='Consultar el informe de validación',faqlabel='ALGUNAS RESPUESTAS',faqtitle='Antes del siguiente paso.',faqs=[('¿Es una app oficial de Nike?','No. Open Adapt es un proyecto independiente de la comunidad, sin afiliación ni respaldo de Nike. Las marcas de Nike pertenecen a sus respectivos titulares.'),('¿Las actualizaciones conservan el emparejamiento?','Una actualización sobre la app instalada, con el mismo paquete y firma, conserva sus datos locales. Sigue siendo necesario el primer emparejamiento real. Falta validar la reconexión con zapatillas físicas tras actualizar. Desinstalar o borrar el almacenamiento elimina los datos.'),('¿Puede clonar el firmware de una zapatilla a la otra?','No. El proyecto consulta diagnósticos del firmware, pero no extrae ni restaura una imagen completa. Que coincidan los números de versión no demuestra que las imágenes sean intercambiables.'),('¿El Swoosh y cada movimiento realmente se iluminan?','El Swoosh iluminado de la ilustración es un recurso artístico. Los efectos reales dependen del hardware y firmware compatibles. Los giros del teléfono no identifican cada pisada.')],donatelabel='QUE EL PROYECTO SIGA',donatetitle='Ayuda a escribir el<br>siguiente capítulo.',donatetext='Si compartes la idea de dar una segunda vida a las Adapt, puedes apoyar el tiempo dedicado a investigar, probar y documentar.',donate='Donar con PayPal',donatenote='Apoyo opcional a través de PayPal. Donar no garantiza compatibilidad ni funciones futuras.',footer='Independiente de Nike. Hecho para una segunda vida.',top='Volver arriba',skip='Ir al contenido',privacy='Este sitio no añade analítica ni cookies de seguimiento. GitHub aloja estas páginas; los enlaces a GitHub y PayPal abren sus propios servicios.')}
for lang,t in translations.items():
 p=t['prefix'];url=base+('es/' if lang=='es' else '')
 nav=''.join(f'<a href="#{i}">{x}</a>' for i,x in zip(t['navid'],t['nav']))
 features=''.join(f'<article class="feature"><span class="feature-icon">{icon(i)}</span><h3>{title}</h3><p>{body}</p></article>' for i,title,body in t['features'])
 steps=''.join(f'<li><span class="step-num">0{n}</span><h3>{title}</h3><p>{body}</p></li>' for n,(title,body) in enumerate(t['steps'],1))
 faq=''.join(f'<details><summary>{html.escape(q)}<span aria-hidden="true">+</span></summary><p>{html.escape(a)}</p></details>' for q,a in t['faqs'])
 schema={'@context':'https://schema.org','@type':'SoftwareApplication','name':'Open Adapt — Nike Adapt Max Revive again','applicationCategory':'UtilitiesApplication','operatingSystem':'Android 7.0+','softwareVersion':'0.3.0','inLanguage':'es','url':url,'downloadUrl':release,'description':t['description'],'offers':{'@type':'Offer','price':'0','priceCurrency':'USD'},'author':{'@type':'Person','name':'danielrodrigohub','url':'https://github.com/danielrodrigohub'}}
 text=f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark light"><meta name="theme-color" content="#0c1215">
<title>{t['title']}</title><meta name="description" content="{t['description']}"><link rel="canonical" href="{url}"><link rel="alternate" hreflang="en" href="{base}"><link rel="alternate" hreflang="es" href="{base}es/"><link rel="alternate" hreflang="x-default" href="{base}">
<meta property="og:type" content="website"><meta property="og:site_name" content="Open Adapt"><meta property="og:title" content="{t['title']}"><meta property="og:description" content="{t['description']}"><meta property="og:url" content="{url}"><meta property="og:locale" content="{'es_CL' if lang=='es' else 'en_US'}"><meta property="og:locale:alternate" content="{'en_US' if lang=='es' else 'es_CL'}"><meta property="og:image" content="{base}assets/revive-banner.png"><meta property="og:image:alt" content="Open Adapt: Auto Max concept with an illuminated teal Swoosh"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{t['title']}"><meta name="twitter:description" content="{t['description']}"><meta name="twitter:image" content="{base}assets/revive-banner.png">
<link rel="icon" type="image/svg+xml" href="{p}assets/favicon.svg"><link rel="stylesheet" href="{p}assets/style.css"><link rel="preload" href="{p}assets/auto-max.png" as="image"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script><script src="{p}assets/site.js" defer></script></head>
<body id="top"><a class="skip" href="#main">{t['skip']}</a>
<header class="header"><a class="brand" href="{p or './'}" aria-label="Open Adapt home"><span class="brand-mark" aria-hidden="true">oa<span>↗</span></span><span>OPEN ADAPT<small>REVIVE AGAIN</small></span></a><nav aria-label="{'Principal' if lang=='es' else 'Main'}">{nav}</nav><div class="header-actions"><a class="language" href="{t['otherlink']}" lang="{'en' if lang=='es' else 'es'}" hreflang="{'en' if lang=='es' else 'es'}">{icon('globe')}{t['other']}</a><a class="support-link" href="{donate}">{t['support']}{icon('heart')}</a></div></header>
<main id="main"><section class="hero wrap" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow"><span class="live-dot"></span>{t['label']}</p><h1 id="hero-title">{t['headline']}</h1><p class="hero-intro">{t['intro']}</p><div class="actions"><a class="button primary" href="{release}">{icon('download')}{t['download']}</a><a class="text-link" href="{repo}">{t['source']}{icon('arrow')}</a></div><p class="release-label"><span></span>{t['experimental']}</p></div><figure class="hero-art"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="art-index">AIR / AUTO MAX</span><img src="{p}assets/auto-max.png" width="1536" height="1024" alt="Nike Adapt Auto Max: gray mesh, teal Swoosh and orange Air sole" fetchpriority="high" decoding="async"><figcaption>{t['art']}</figcaption><span class="coordinate" aria-hidden="true">ADAPT / 001</span></figure><div class="hero-bottom"><span>{t['scroll']}</span><span>NIKE ADAPT MAX REVIVE AGAIN</span><a href="#story" aria-label="{t['nav'][0]}">↓</a></div></section>
<div class="spec-strip"><span>OPEN ADAPT</span>{''.join('<span>'+x+'</span>' for x in t['spec'])}<span>↗ REVIVE AGAIN</span></div>
<section id="story" class="story wrap section"><div><p class="eyebrow">{t['storylabel']}</p><h2>{t['storytitle']}</h2><p class="question">Why nike discontinued this?...</p></div><div class="story-words"><blockquote>{t['quote']}</blockquote><p>{t['storybody']}</p><p class="fine">{t['storynote']}</p></div></section>
<section id="features" class="features-section"><div class="wrap section"><div class="section-heading"><div><p class="eyebrow">{t['featurelabel']}</p><h2>{t['featuretitle']}</h2></div><span class="big-index" aria-hidden="true">02</span></div><div class="feature-grid">{features}</div></div></section>
<section id="app" class="app-section wrap section"><div class="app-copy"><p class="eyebrow">{t['applabel']}</p><h2>{t['apptitle']}</h2><p>{t['apptext']}</p><ul class="app-tabs">{''.join('<li>'+icon('check')+x+'</li>' for x in t['apptabs'])}</ul><p class="fine">{t['apknote']}</p><a class="text-link" href="{repo}/blob/main/output/VALIDACION.md">{t['validation']}{icon('arrow')}</a></div><div class="app-visual"><div class="app-screens"><img src="{p}assets/app-home.png" width="1080" height="2400" loading="lazy" alt="Open Adapt Home: Auto Max artwork and separate battery cards"><img src="{p}assets/app-lights.png" width="1080" height="2400" loading="lazy" alt="Open Adapt Lights: color selection and continuous-light controls"></div><p class="fine">{t['screenshot']}</p></div></section>
<section id="start" class="start-section"><div class="wrap section"><p class="eyebrow">{t['startlabel']}</p><h2>{t['starttitle']}</h2><ol class="steps">{steps}</ol><div class="actions"><a class="button dark" href="{release}">{icon('download')}{t['download']}</a><a class="text-link" href="{repo}/blob/main/output/LEEME.md">{t['guide']}{icon('arrow')}</a><a class="text-link" href="{repo}/blob/main/docs/UPDATES.md">{t['updates']}{icon('arrow')}</a></div></div></section>
<section class="status wrap section"><div class="status-heading"><span class="status-icon">{icon('code')}</span><p class="eyebrow">{t['statuslabel']}</p><h2>{t['statustitle']}</h2></div><div><p>{t['status']}</p><p>{t['motor']}</p><a class="text-link" href="{repo}/blob/main/output/VALIDACION.md">{t['validation']}{icon('arrow')}</a></div></section>
<section class="faq wrap section"><div><p class="eyebrow">{t['faqlabel']}</p><h2>{t['faqtitle']}</h2></div><div class="faq-list">{faq}</div></section>
<section id="support" class="donation wrap"><div class="donation-orbit" aria-hidden="true"></div><div><p class="eyebrow">{t['donatelabel']}</p><h2>{t['donatetitle']}</h2><p>{t['donatetext']}</p></div><div class="donation-action"><span class="heart-large">{icon('heart')}</span><a class="button primary" href="{donate}">{icon('heart')}{t['donate']}</a><p class="fine">{t['donatenote']}</p></div></section></main>
<footer class="footer wrap"><div class="footer-top"><a class="brand" href="#top"><span class="brand-mark" aria-hidden="true">oa<span>↗</span></span><span>OPEN ADAPT<small>REVIVE AGAIN</small></span></a><p>{t['footer']}</p><a class="text-link" href="{repo}">GitHub{icon('arrow')}</a><a class="text-link" href="{t['otherlink']}">{t['other']}{icon('globe')}</a><a class="back-top" href="#top" aria-label="{t['top']}">↑</a></div><p class="fine">{t['privacy']}</p><p class="fine">© 2026 Open Adapt · Nike Adapt Max Revive again · <a href="{repo}/blob/main/README.md#-independent-by-design">Independent project / Proyecto independiente</a></p></footer></body></html>'''
 target=site/('es/index.html' if lang=='es' else 'index.html');target.parent.mkdir(parents=True,exist_ok=True);target.write_text(text)
(site/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n'+''.join('<url><loc>'+url+'</loc><xhtml:link rel="alternate" hreflang="en" href="'+base+'"/><xhtml:link rel="alternate" hreflang="es" href="'+base+'es/"/></url>\n' for url in [base,base+'es/'])+'</urlset>\n')
(site/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+base+'sitemap.xml\n')
(site/'.nojekyll').write_text('')
print('Built English and Spanish static pages, sitemap and robots file.')
